import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 250005;
    static long total, maxKVal, modVal;
    static long[] factArr = new long[MAX_SIZE];
    static long[] invFactArr = new long[MAX_SIZE];
    static long[][] dpCache = new long[26][MAX_SIZE];

    static long binPow(long base, long exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % modVal;
            base = base * base % modVal;
            exp >>= 1;
        }
        return res;
    }

    static int getBit(int x) {
        return x & (-x);
    }

    static long recurseDP(int level, int mask) {
        if (dpCache[level][mask] != -1) return dpCache[level][mask];
        if (mask == 0) {
            long res = factArr[(int) total];
            for (int i = 1; i <= level; i++)
                res = res * (maxKVal - i + 1) % modVal;
            dpCache[level][mask] = res;
            return res;
        }
        long res = 0;
        int tmp_mask = mask - getBit(mask);
        for (int sub_mask = tmp_mask; sub_mask > 0; sub_mask = (sub_mask - 1) & tmp_mask)
            res = (res + invFactArr[mask - sub_mask] * recurseDP(level + 1, sub_mask)) % modVal;
        res = (res + invFactArr[mask] * recurseDP(level + 1, 0)) % modVal;
        dpCache[level][mask] = res;
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total = sc.nextLong();
        maxKVal = sc.nextLong();
        modVal = sc.nextLong();

        long answer = binPow(maxKVal, total);
        if ((total & 1) == 1) {
            System.out.println(answer);
            sc.close();
            return;
        }

        factArr[0] = 1;
        for (int i = 1; i <= total; i++) {
            factArr[i] = factArr[i - 1] * i % modVal;
        }

        invFactArr[(int) total] = binPow(factArr[(int) total], modVal - 2);
        for (int i = (int) total; i > 0; i--) {
            invFactArr[i - 1] = invFactArr[i] * i % modVal;
        }

        for (int i = 0; i < 26; i++) {
            for (int j = 0; j <= total; j++) {
                dpCache[i][j] = -1;
            }
        }

        answer = (answer - recurseDP(0, (int) total) + modVal) % modVal;
        System.out.println(answer);
        sc.close();
    }
}
